function rigData(){return{version:1,targetUuid:R.target?.uuid||R.layer?.userData?.targetUuid||'',nodes:R.nodes.map(n=>({id:n.id,name:n.name,p:[...n.p]})),edges:R.edges.map(e=>({id:e.id,a:e.a,b:e.b,control:[...e.control],waveCount:+e.waveCount||0,waveAmp:+e.waveAmp||0}))}}
