function ensureRigGhost(){ensureRigVisual();if(!R.ghostNode){R.ghostNode=new THREE.Mesh(new THREE.SphereGeometry(.075,14,10),new THREE.MeshBasicMaterial({color:0x32cd32,transparent:true,opacity:.8,depthTest:false}));R.ghostNode.renderOrder=9997;R.ghostNode.userData.savanskiRigVisual=true;R.visual.add(R.ghostNode)}if(!R.ghostEdge){R.ghostEdge=new THREE.Line(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color:0xfff600,transparent:true,opacity:.9,depthTest:false}));R.ghostEdge.renderOrder=9996;R.ghostEdge.userData.savanskiRigVisual=true;R.visual.add(R.ghostEdge)}return{node:R.ghostNode,edge:R.ghostEdge}}
