function addNodeWorld(p,name='Joint'){const n={id:uid('joint'),name:`${name} ${R.nodes.length+1}`,p:worldToRigLocal(p).toArray()};R.nodes.push(n);return n}
function addEdge(a,b){if(!a||!b||a===b)return null;if(R.edges.some(e=>(e.a===a&&e.b===b)||(e.a===b&&e.b===a)))return null;const e={id:uid('bone'),a,b,control:[0,0,0],waveCount:0,waveAmp:0};R.edges.push(e);return e}
function selectNode(id){R.selectedNode=id;R.selectedEdge=null;rebuildRigVisual();syncRigReadout()}
function selectEdge(id){R.selectedEdge=id;R.selectedNode=null;rebuildRigVisual();syncRigReadout()}
function graphDegrees(){const m=new Map(R.nodes.map(n=>[n.id,0]));for(const e of R.edges){m.set(e.a,(m.get(e.a)||0)+1);m.set(e.b,(m.get(e.b)||0)+1)}return m}
function mergeNodes(sourceId,targetId){if(!sourceId||!targetId||sourceId===targetId)return;for(const e of R.edges){if(e.a===sourceId)e.a=targetId;if(e.b===sourceId)e.b=targetId}R.edges=R.edges.filter((e,i,a)=>e.a!==e.b&&a.findIndex(q=>((q.a===e.a&&q.b===e.b)||(q.a===e.b&&q.b===e.a)))===i);R.nodes=R.nodes.filter(n=>n.id!==sourceId);if(R.anchor===sourceId)R.anchor=targetId;if(R.selectedNode===sourceId)R.selectedNode=targetId;rebuildRigVisual();syncRigReadout()}
function drawRigClick(e){const snap=nearestNodeScreen(e,null);if(!R.anchor){let start=snap;if(!start){const p=rigPointFromEvent(e);if(!p)return;start=addNodeWorld(p)}R.anchor=start.id;selectNode(start.id);return}let dest=snap;if(dest?.id===R.anchor)dest=null;if(!dest){const p=rigPointFromEvent(e);if(!p)return;dest=addNodeWorld(p)}const edge=addEdge(R.anchor,dest.id);R.anchor=dest.id;R.selectedNode=dest.id;R.selectedEdge=edge?.id||null;rebuildRigVisual();syncRigReadout()}
function rayVisual(e){const rect=S.renderer.domElement.getBoundingClientRect();S.pointer.set((e.clientX-rect.left)/rect.width*2-1,-((e.clientY-rect.top)/rect.height*2-1));S.raycaster.setFromCamera(S.pointer,S.camera);return S.raycaster.intersectObjects(R.visual?.children||[],false)[0]||null}
function startRigDrag(e){const h=rayVisual(e);if(!h)return false;if(h.object.userData.rigNodeId){const id=h.object.userData.rigNodeId;selectNode(id);const n=R.nodes.find(x=>x.id===id),point=nodeWorld(n),normal=S.camera.getWorldDirection(new THREE.Vector3()).normalize(),plane=new THREE.Plane().setFromNormalAndCoplanarPoint(normal,point);R.drag={kind:'node',id,plane};S.orbit.enabled=false;return true}if(h.object.userData.rigHandleEdgeId){const id=h.object.userData.rigHandleEdgeId;selectEdge(id);const e0=R.edges.find(x=>x.id===id),ec=edgeCurve(e0),normal=S.camera.getWorldDirection(new THREE.Vector3()).normalize(),plane=new THREE.Plane().setFromNormalAndCoplanarPoint(normal,ec.c);R.drag={kind:'handle',id,plane};S.orbit.enabled=false;return true}if(h.object.userData.rigEdgeId){selectEdge(h.object.userData.rigEdgeId);return true}return false}
function updateRigDrag(e){if(!R.drag)return;const p=new THREE.Vector3();const rect=S.renderer.domElement.getBoundingClientRect();S.pointer.set((e.clientX-rect.left)/rect.width*2-1,-((e.clientY-rect.top)/rect.height*2-1));S.raycaster.setFromCamera(S.pointer,S.camera);if(!S.raycaster.ray.intersectPlane(R.drag.plane,p))return;if(R.drag.kind==='node'){const n=R.nodes.find(x=>x.id===R.drag.id);if(n)setNodeWorld(n,p)}else if(R.drag.kind==='handle'){const edge=R.edges.find(x=>x.id===R.drag.id),ec=edge&&edgeCurve(edge);if(ec){const worldOff=p.clone().sub(ec.a.clone().add(ec.b).multiplyScalar(.5));if(R.layer){const q=R.layer.getWorldQuaternion(new THREE.Quaternion()).invert();worldOff.applyQuaternion(q);const sc=R.layer.getWorldScale(new THREE.Vector3());worldOff.set(worldOff.x/(sc.x||1),worldOff.y/(sc.y||1),worldOff.z/(sc.z||1))}edge.control=worldOff.toArray()}}rebuildRigVisual();syncRigReadout()}
