function handleRigPointerDown(e){if(!R.enabled)return false;if(R.mode==='draw'){drawRigClick(e);return true}if(R.mode==='merge'){const h=rayVisual(e);const id=h?.object?.userData?.rigNodeId;if(id){if(!R.mergeSource){R.mergeSource=id;selectNode(id);A.toast('Select the joint to merge into.')}else{mergeNodes(R.mergeSource,id);R.mergeSource=null;R.mode='edit';control('rig-mode').value='edit';persistRigData();A.toast('Joints merged into one shared joint.','success')}}return true}return startRigDrag(e)}
function handleRigPointerMove(e){if(!R.enabled)return false;if(R.mode==='draw')updateRigGhost(e);else if(R.drag)updateRigDrag(e);return true}
function handleRigPointerUp(){if(!R.enabled)return false;endRigDrag();return true}
function setBubbleRig(on){R.enabled=!!on;if(on){P.enabled&&setVolumePaint(false);S.sculpt&&A.setSculptMode?.(false);S.directPaint&&A.setDirectPaint?.(false);S.weightPaint=false;S.bubbleRig=true;S.transform&&(S.transform.enabled=false);R.target=selectedRigTarget();if(!R.target||R.target.userData?.savanskiRigLayer){R.target=A.meshes()[0]||null}loadSavedRigForTarget(R.target);ensureRigVisual();rebuildRigVisual();A.setMode('bubble rig')}else{S.bubbleRig=false;S.transform&&(S.transform.enabled=true);R.anchor=null;R.drag=null;R.mergeSource=null;clearRigGhost();S.orbit&&(S.orbit.enabled=true);A.setMode('select');if(R.visual)R.visual.visible=!!R.layer}const b=root()?.querySelector('[data-organic-action="rig-toggle"]');if(b){b.setAttribute('aria-pressed',String(on));b.textContent=on?'Disable Bubble Rig':'Enable Bubble Rig'}syncRigReadout();A.toast(on?'Bubble rigging enabled — click to draw connected joints':'Bubble rigging disabled')}
