function deleteJoint(){const id=R.selectedNode;if(!id)return;R.nodes=R.nodes.filter(n=>n.id!==id);R.edges=R.edges.filter(e=>e.a!==id&&e.b!==id);if(R.anchor===id)R.anchor=null;R.selectedNode=null;rebuildRigVisual();persistRigData();syncRigReadout()}
function deleteSegment(){const id=R.selectedEdge;if(!id)return;R.edges=R.edges.filter(e=>e.id!==id);R.selectedEdge=null;rebuildRigVisual();persistRigData();syncRigReadout()}
function mirrorRig(branchOnly=false){if(!R.nodes.length)return;const st=paintSettings(),axis=control('rig-mirror-axis')?.value||st.axis||'x',center=constructionCenter();let sourceNodes=[...R.nodes],sourceEdges=[...R.edges];if(branchOnly&&R.selectedNode){const nodeIds=new Set([R.selectedNode]),edges=[];const queue=[R.selectedNode];while(queue.length){const id=queue.shift();for(const e of R.edges){if(e.a!==id||nodeIds.has(e.b))continue;edges.push(e);nodeIds.add(e.b);queue.push(e.b)}}sourceNodes=R.nodes.filter(n=>nodeIds.has(n.id));sourceEdges=edges}const map=new Map();for(const n of sourceNodes){const w=nodeWorld(n);if(Math.abs(w[axis]-center[axis])<1e-5){map.set(n.id,n.id);continue}const mw=w.clone();mw[axis]=2*center[axis]-mw[axis];let shared=R.nodes.find(q=>nodeWorld(q).distanceToSquared(mw)<1e-8);if(!shared)shared=addNodeWorld(mw,'Mirrored Joint');map.set(n.id,shared.id)}for(const e of sourceEdges){const a=map.get(e.a),b=map.get(e.b);if(!a||!b||a===b)continue;const ne=addEdge(a,b);if(ne){const co=new THREE.Vector3().fromArray(e.control);co[axis]*=-1;ne.control=co.toArray();ne.waveCount=+e.waveCount||0;ne.waveAmp=+e.waveAmp||0}}rebuildRigVisual();persistRigData();A.toast(`${branchOnly?'Selected rig branch':'Rig'} mirrored across ${axis.toUpperCase()} axis. Both sides are independently editable.`,'success')}
function applyConnectorShape(){const e=R.edges.find(x=>x.id===R.selectedEdge);if(!e)return A.toast('Select a bone connector first.','error');e.waveCount=Math.max(0,Math.min(8,+control('rig-wave-count')?.value||0));e.waveAmp=Math.max(0,Math.min(2,+control('rig-wave-amp')?.value||0));rebuildRigVisual();persistRigData();A.toast(e.waveCount&&e.waveAmp?'Connector reshaped with a wavy anatomical path.':'Connector wave removed.','success')}
function straightenConnector(){const e=R.edges.find(x=>x.id===R.selectedEdge);if(!e)return A.toast('Select a bone connector first.','error');e.control=[0,0,0];e.waveCount=0;e.waveAmp=0;if(control('rig-wave-count'))control('rig-wave-count').value=0;if(control('rig-wave-amp'))control('rig-wave-amp').value=0;rebuildRigVisual();persistRigData();A.toast('Connector straightened')}
function flipRig(axis){if(!R.layer)return A.toast('Save the rig layer before flipping the whole rig.','error');A.pushHistory('Flip rig '+axis.toUpperCase());R.layer.scale[axis]*=-1;R.layer.updateMatrixWorld(true);rebuildRigVisual();A.selectObject(R.layer);A.toast(`Rig layer flipped on ${axis.toUpperCase()}`,'success')}
function duplicateRig(){if(!R.layer)return A.toast('Save the rig layer first.','error');const copy=R.layer.clone(false);copy.userData=JSON.parse(JSON.stringify(R.layer.userData));copy.name=R.layer.name+' Copy';copy.position.copy(R.layer.position).add(new THREE.Vector3(.25,0,.25));A.ensureRoot().add(copy);A.selectObject(copy);A.refreshSceneList();A.toast('Rig layer duplicated','success')}
function persistRigData(){if(!R.layer)return;R.layer.userData.savanskiBubbleRig=rigData();R.layer.userData.targetUuid=R.target?.uuid||R.layer.userData.targetUuid||'';S.projectMeta.edits++}
function saveRig(){if(!R.nodes.length)return A.toast('Draw at least one rig joint first.','error');if(!R.target)R.target=selectedRigTarget()||A.meshes()[0];if(!R.layer){R.layer=new THREE.Group();R.layer.name=`Rig Layer — ${R.target?.name||'Model'}`;R.layer.userData.savanskiRigLayer=true;R.layer.userData.targetUuid=R.target?.uuid||'';A.ensureRoot().add(R.layer)}persistRigData();A.selectObject(R.layer);A.refreshSceneList();rebuildRigVisual();A.toast('Rig saved as an editable Rig Layer. Select the layer to move, rotate, or scale the whole rig.','success')}
function loadRigLayer(layer){if(!layer?.userData?.savanskiBubbleRig)return false;R.layer=layer;const d=copyRigData(layer.userData.savanskiBubbleRig);R.nodes=d.nodes;R.edges=d.edges;R.target=findObjectByUuid(layer.userData.targetUuid)||null;R.anchor=null;R.selectedNode=null;R.selectedEdge=null;rebuildRigVisual();syncRigReadout();return true}
function loadSavedRigForTarget(target){if(R.layer&&R.layer.parent&&(!target||R.layer.userData.targetUuid===target.uuid))return loadRigLayer(R.layer);const layer=S.root?.children?.find(o=>o.isGroup&&o.userData?.savanskiRigLayer&&(!target||o.userData.targetUuid===target.uuid));if(layer)return loadRigLayer(layer);R.layer=null;R.nodes=[];R.edges=[];R.anchor=null;R.selectedNode=null;R.selectedEdge=null;R.target=target||null;rebuildRigVisual();syncRigReadout();return false}
function syncRigReadout(){const host=root()?.querySelector('[data-organic-rig-readout]');if(!host)return;const deg=graphDegrees(),branches=[...deg.values()].filter(v=>v>2).length;const sn=R.nodes.find(n=>n.id===R.selectedNode),se=R.edges.find(e=>e.id===R.selectedEdge);host.innerHTML=`<div class="sav-live-item">Joints: ${R.nodes.length}</div><div class="sav-live-item">Bones: ${R.edges.length}</div><div class="sav-live-item">Branches: ${branches}</div><div class="sav-live-item">${R.layer?'Rig Layer saved':'Rig not saved yet'}</div>${sn?`<div class="sav-live-item">Selected joint: ${A.escapeHtml(sn.name)}</div>`:''}${se?`<div class="sav-live-item">Selected connector: ${A.escapeHtml(se.id)}</div>`:''}`}
function buildBoneTree(){if(!R.nodes.length||!R.edges.length)return null;const deg=graphDegrees(),rootNode=R.nodes.find(n=>(deg.get(n.id)||0)===1)||R.nodes[0],boneMap=new Map(),bones=[],rootGroup=new THREE.Group();rootGroup.name='Bubble Rig Skeleton';rootGroup.userData.savanskiSkeletonRoot=true;rootGroup.userData.rigLayerUuid=R.layer?.uuid||'';for(const old of [...(S.root?.children||[])])if(old!==rootGroup&&old.userData?.savanskiSkeletonRoot&&old.userData?.rigLayerUuid===rootGroup.userData.rigLayerUuid)old.parent?.remove(old);A.ensureRoot().add(rootGroup);S.root.updateWorldMatrix(true,false);const rootInv=S.root.matrixWorld.clone().invert(),rootLocal=new Map(R.nodes.map(n=>[n.id,nodeWorld(n).applyMatrix4(rootInv)]));const make=(n,parentBone=null,parentNodeId=null)=>{let b=boneMap.get(n.id);if(b)return b;b=new THREE.Bone();b.name=`SV_${(n.name||'Joint').replace(/[^A-Za-z0-9_-]+/g,'_')}`;const p=rootLocal.get(n.id).clone();if(parentBone&&parentNodeId)p.sub(rootLocal.get(parentNodeId));b.position.copy(p);(parentBone||rootGroup).add(b);boneMap.set(n.id,b);bones.push(b);return b};const visitedEdges=new Set(),walk=(nodeId,parentBone,parentNodeId=null)=>{const n=R.nodes.find(q=>q.id===nodeId);const b=make(n,parentBone,parentNodeId);for(const e of R.edges){if(visitedEdges.has(e.id))continue;let other=null;if(e.a===nodeId)other=e.b;else if(e.b===nodeId)other=e.a;else continue;visitedEdges.add(e.id);if(boneMap.has(other))continue;walk(other,b,nodeId)}return b};walk(rootNode.id,null,null);for(const n of R.nodes)if(!boneMap.has(n.id))make(n,null,null);rootGroup.updateMatrixWorld(true);return{rootGroup,bones,boneMap}}
function meshesForTarget(target){const out=[];if(target?.isMesh)out.push(target);else target?.traverse?.(o=>o.isMesh&&out.push(o));return out.filter(m=>!m.userData?.savanskiRigVisual)}
function skinMesh(mesh,bones,skeleton){mesh.updateWorldMatrix(true,false);const g=mesh.geometry.clone(),pos=g.getAttribute('position');if(!pos)return null;const idx=new Uint16Array(pos.count*4),wts=new Float32Array(pos.count*4),v=new THREE.Vector3(),boneWorld=bones.map(b=>b.getWorldPosition(new THREE.Vector3()));for(let i=0;i<pos.count;i++){v.fromBufferAttribute(pos,i).applyMatrix4(mesh.matrixWorld);const ranked=boneWorld.map((p,j)=>({j,d:Math.max(1e-5,v.distanceTo(p))})).sort((a,b)=>a.d-b.d).slice(0,4);let sum=0;for(let k=0;k<4;k++){const q=ranked[k]||ranked[0];idx[i*4+k]=q?.j||0;const w=q?1/(q.d*q.d):0;wts[i*4+k]=w;sum+=w}if(sum<=0)sum=1;for(let k=0;k<4;k++)wts[i*4+k]/=sum}g.setAttribute('skinIndex',new THREE.Uint16BufferAttribute(idx,4));g.setAttribute('skinWeight',new THREE.Float32BufferAttribute(wts,4));const mat=Array.isArray(mesh.material)?mesh.material.map(m=>m.clone()):mesh.material.clone(),skin=new THREE.SkinnedMesh(g,mat);skin.name=mesh.name||'Rigged Mesh';skin.position.copy(mesh.position);skin.quaternion.copy(mesh.quaternion);skin.scale.copy(mesh.scale);skin.visible=mesh.visible;skin.castShadow=mesh.castShadow;skin.receiveShadow=mesh.receiveShadow;skin.userData={...mesh.userData,savanskiBubbleRigged:true};const parent=mesh.parent,index=parent.children.indexOf(mesh);parent.remove(mesh);parent.add(skin);if(index>=0){parent.children.splice(parent.children.indexOf(skin),1);parent.children.splice(index,0,skin)}skin.updateMatrixWorld(true);skin.bind(skeleton,skin.matrixWorld);mesh.geometry?.dispose?.();const ms=Array.isArray(mesh.material)?mesh.material:[mesh.material];ms.filter(Boolean).forEach(m=>m.dispose?.());return skin}
function applyRig(){if(!R.layer)saveRig();if(!R.layer||R.edges.length<1)return;R.target=R.target||findObjectByUuid(R.layer.userData.targetUuid)||selectedRigTarget();const targets=meshesForTarget(R.target);if(!targets.length)return A.toast('The rig needs a mesh or grouped meshes to bind.','error');A.pushHistory('Apply bubble rig');const built=buildBoneTree();if(!built)return;const skeleton=new THREE.Skeleton(built.bones),skins=[];for(const m of targets){const s=skinMesh(m,built.bones,skeleton);if(s)skins.push(s)}if(!skins.length){built.rootGroup.parent?.remove(built.rootGroup);return A.toast('Rig binding failed.','error')}R.target=skins.length===1?skins[0]:(R.target?.isGroup?R.target:skins[0]);R.layer.userData.targetUuid=R.target.uuid;R.layer.userData.savanskiBubbleRig=rigData();S.riggedMesh=skins[0];if(S.skeletonHelper){S.scene.remove(S.skeletonHelper);S.skeletonHelper.dispose?.()}S.skeletonHelper=new THREE.SkeletonHelper(built.rootGroup);S.skeletonHelper.material.depthTest=false;S.skeletonHelper.renderOrder=9993;S.scene.add(S.skeletonHelper);A.selectObject(skins[0]);A.refreshSceneList();A.updateProjectStats();A.toast(`Bubble rig applied with automatic weights to ${skins.length} mesh${skins.length===1?'':'es'}. Refine weights in the existing Weight Paint tools.`,'success')}
function selectRigLayer(){if(R.layer)A.selectObject(R.layer);else A.toast('Save the rig first.','error')}

